//! **Semi2k** — additive sharing mod `2^k`, dishonest majority, semi-honest,
//! with Beaver triples generated by **real oblivious transfer**.
//!
//! # Why this exists
//!
//! `docs/research-agenda.md` §4 reports that a wide encrypted linear layer moves
//! to FHE under a *dishonest* majority and stays on MPC under an *honest* one. The
//! honest-majority arm is measured (`bench-hybrid-nn`, ABY3). The dishonest arm was
//! a **prediction**, because the artifact had no dishonest-majority protocol that
//! actually ran — and the prediction rests entirely on the claim that a Beaver
//! triple costs ~3.1 KB of preprocessing.
//!
//! This engine makes that measurable. The online phase is Dealer's, which
//! `baru mpcc calibrate` already validates at 0% error; the difference is that
//! the triples are produced by running Gilboa's OLE over the IKNP correlated OT in
//! [`crate::ot::iknp::correlated`], and the OT traffic is counted. So
//! `offline_bytes` is a measurement, and [`crate::mpcc::ot_cost`]'s derivation can
//! be checked against it rather than trusted.
//!
//! # Triple generation
//!
//! Two parties, `a = a₀ + a₁`, `b = b₀ + b₁`, and
//!
//! ```text
//! c = a·b = a₀b₀ + a₁b₁ + a₀b₁ + a₁b₀
//!           └ local ┘   └── needs OLE ──┘
//! ```
//!
//! Each cross term is one **Gilboa OLE**: to share `x·y` with `x` at one party and
//! `y` at the other, the `x`-holder acts as OT receiver with `x`'s bits as choice
//! bits, and the `y`-holder offers the correlation `2ⁱ·y` on OT `i`. Summing the
//! receiver's outputs gives `x·y` plus a mask the sender holds, i.e. an additive
//! sharing. That is `k` correlated OTs per cross term, so **`2k` per triple** —
//! the count `ot_cost` prices from.
//!
//! All the OTs for a whole batch of triples run in **one** extension call, which
//! is what a real implementation does and what makes the per-triple cost the
//! amortized figure rather than the first-triple figure.
//!
//! # Scope, stated
//!
//! * **Two parties.** Gilboa OLE is pairwise; `n` parties need `n(n−1)` cross
//!   terms. Two is the interesting dishonest-majority case and the setting the
//!   hybrid literature (Gazelle, Delphi, Cheetah) works in.
//! * **Semi-honest.** No MACs, no sacrifice — this is Semi2k, not SPDZ2k. A
//!   malicious party can deviate freely. [`crate::mpcc::spdz2k`] is the
//!   authenticated upgrade; it keeps this engine as the baseline the MAC
//!   overhead is measured against, and pays for the `s` extra ring bits that
//!   make a MAC over `Z_2^k` sound at all.
//! * The OT is [`crate::ot::iknp`], which has **no KOS consistency check**, so this
//!   inherits that limitation and cannot be cited as maliciously secure.
//! * Random bits are drawn locally and counted, exactly as `DealerEngine` does —
//!   the same simplification, documented in `crate::mpcc::vm`.

use rand::Rng;

use super::vm::{Counters, Modulus, ShareEngine};

/// One party's additive share; the simulation holds every party's view.
pub type Additive = Vec<u64>;

pub struct Semi2kEngine {
    m: Modulus,
    counters: Counters,
    /// Triples not yet consumed, generated in batches by real OT.
    pool: Vec<(Additive, Additive, Additive)>,
    /// How many triples each OT batch produces.
    batch: usize,
}

impl Semi2kEngine {
    pub fn new(parties: usize, bits: u32) -> Result<Self, String> {
        if parties != 2 {
            return Err(format!(
                "semi2k here is two-party (Gilboa OLE is pairwise); got {parties} parties"
            ));
        }
        if bits > 64 {
            return Err(format!("semi2k: k = {bits} exceeds 64"));
        }
        Ok(Semi2kEngine {
            m: Modulus::Ring { k: bits },
            counters: Counters::default(),
            pool: Vec::new(),
            batch: 64,
        })
    }

    fn mask(&self) -> u64 {
        match self.m {
            Modulus::Ring { k } if k >= 64 => u64::MAX,
            Modulus::Ring { k } => (1u64 << k) - 1,
            _ => u64::MAX,
        }
    }

    fn bits(&self) -> u32 {
        match self.m {
            Modulus::Ring { k } => k,
            _ => 64,
        }
    }

    fn charge(&mut self, elems: u64) {
        // One peer, matching `DealerEngine`'s convention so the two are
        // comparable against the same prediction.
        self.counters.online_bytes += elems * self.m.element_bytes();
    }

    /// Additively share `x·y` where party 0 holds `x` and party 1 holds `y`,
    /// using `k` correlated OTs. Returns `(share0, share1)`.
    ///
    /// Party 0 is the OT receiver, choosing on the bits of `x`; party 1 offers
    /// `2ⁱ·y` as the correlation on OT `i`, so party 0's summed outputs are
    /// `x·y + Σrᵢ` and party 1 keeps `−Σrᵢ`.
    fn ole_batch(&mut self, pairs: &[(u64, u64)]) -> Result<Vec<(u64, u64)>, String> {
        let k = self.bits();
        let mask = self.mask();
        let mut choices: Vec<bool> = Vec::with_capacity(pairs.len() * k as usize);
        let mut deltas: Vec<u64> = Vec::with_capacity(pairs.len() * k as usize);
        for (x, y) in pairs {
            for i in 0..k {
                choices.push((x >> i) & 1 == 1);
                deltas.push(y.wrapping_shl(i) & mask);
            }
        }
        let cot = crate::ot::iknp::correlated(&choices, &deltas, k)?;
        // Real OT traffic — this is the number the cost model is checked against.
        self.counters.offline_bytes += cot.traffic.total() as u64;

        let mut out = Vec::with_capacity(pairs.len());
        for j in 0..pairs.len() {
            let lo = j * k as usize;
            let mut s0 = 0u64;
            let mut s1 = 0u64;
            for i in 0..k as usize {
                s0 = s0.wrapping_add(cot.receiver[lo + i]) & mask;
                s1 = s1.wrapping_sub(cot.sender_r[lo + i]) & mask;
            }
            out.push((s0, s1));
        }
        Ok(out)
    }

    /// Run the offline phase for `count` triples in **one** batched OT
    /// extension, so the base-OT phase amortizes exactly as it does in
    /// production. Traffic lands in `counters().offline_bytes`.
    ///
    /// This is the entry point [`crate::bench::triples`] measures: the engine
    /// normally refills lazily when a multiplication runs dry, which is the
    /// wrong shape for isolating preprocessing cost.
    pub fn preprocess(&mut self, count: usize) -> Result<(), String> {
        if count == 0 {
            return Err("preprocess needs a positive triple count".into());
        }
        let previous = self.batch;
        self.batch = count;
        let r = self.refill();
        self.batch = previous;
        r
    }

    /// Generate `self.batch` triples, all their OTs in one extension call.
    fn refill(&mut self) -> Result<(), String> {
        let mask = self.mask();
        let mut rng = rand::thread_rng();
        let n = self.batch;
        let a: Vec<(u64, u64)> = (0..n)
            .map(|_| (rng.gen::<u64>() & mask, rng.gen::<u64>() & mask))
            .collect();
        let b: Vec<(u64, u64)> = (0..n)
            .map(|_| (rng.gen::<u64>() & mask, rng.gen::<u64>() & mask))
            .collect();

        // The two cross terms, batched into one OT extension each.
        let x01: Vec<(u64, u64)> = (0..n).map(|i| (a[i].0, b[i].1)).collect();
        let x10: Vec<(u64, u64)> = (0..n).map(|i| (a[i].1, b[i].0)).collect();
        let s01 = self.ole_batch(&x01)?;
        let s10 = self.ole_batch(&x10)?;

        for i in 0..n {
            // c0 = a0·b0 + [a0b1]_0 + [a1b0]_0,  c1 = a1·b1 + [a0b1]_1 + [a1b0]_1
            let c0 = a[i]
                .0
                .wrapping_mul(b[i].0)
                .wrapping_add(s01[i].0)
                .wrapping_add(s10[i].0)
                & mask;
            let c1 = a[i]
                .1
                .wrapping_mul(b[i].1)
                .wrapping_add(s01[i].1)
                .wrapping_add(s10[i].1)
                & mask;
            self.pool
                .push((vec![a[i].0, a[i].1], vec![b[i].0, b[i].1], vec![c0, c1]));
        }
        self.counters.triples_generated += n as u64;
        Ok(())
    }

    fn triple(&mut self) -> (Additive, Additive, Additive) {
        if self.pool.is_empty() {
            // A failure here is a bug in triple generation, not a protocol
            // outcome, so it is not worth threading a Result through every
            // arithmetic op.
            self.refill().expect("semi2k: OT triple generation failed");
        }
        self.counters.triples += 1;
        self.pool.pop().expect("pool refilled")
    }

    fn reconstruct(&self, s: &Additive) -> u64 {
        s.iter().fold(0u64, |acc, x| self.m.add(acc, *x))
    }
    fn add_pure(&self, a: &Additive, b: &Additive) -> Additive {
        a.iter().zip(b).map(|(x, y)| self.m.add(*x, *y)).collect()
    }
    fn sub_pure(&self, a: &Additive, b: &Additive) -> Additive {
        a.iter().zip(b).map(|(x, y)| self.m.sub(*x, *y)).collect()
    }
    fn mul_const_pure(&self, a: &Additive, c: u64) -> Additive {
        a.iter().map(|x| self.m.mul(*x, c)).collect()
    }
    fn split(&self, value: u64) -> Additive {
        let mut rng = rand::thread_rng();
        let r = rng.gen::<u64>() & self.mask();
        vec![r, self.m.sub(value, r)]
    }
}

impl ShareEngine for Semi2kEngine {
    type Share = Additive;

    fn modulus(&self) -> Modulus {
        self.m
    }
    fn parties(&self) -> usize {
        2
    }
    fn counters(&self) -> &Counters {
        &self.counters
    }

    fn input(&mut self, value: u64, _party: usize) -> Additive {
        self.charge(1);
        self.split(value)
    }
    fn constant(&mut self, value: u64) -> Additive {
        vec![value, 0]
    }

    fn add(&mut self, a: &Additive, b: &Additive) -> Additive {
        self.add_pure(a, b)
    }
    fn sub(&mut self, a: &Additive, b: &Additive) -> Additive {
        self.sub_pure(a, b)
    }
    fn add_const(&mut self, a: &Additive, c: u64) -> Additive {
        let mut out = a.clone();
        out[0] = self.m.add(out[0], c);
        out
    }
    fn mul_const(&mut self, a: &Additive, c: u64) -> Additive {
        self.mul_const_pure(a, c)
    }

    fn mul_batch(&mut self, pairs: &[(Additive, Additive)]) -> Vec<Additive> {
        // Beaver, exactly as Dealer does it — the online phase is what Semi2k
        // shares with the trusted-dealer lower bound. Only the triples differ.
        self.charge(2 * pairs.len() as u64);
        self.counters.muls += pairs.len() as u64;

        let mut out = Vec::with_capacity(pairs.len());
        for (x, y) in pairs {
            let (a, b, ab) = self.triple();
            let d = self.reconstruct(&self.sub_pure(x, &a));
            let e = self.reconstruct(&self.sub_pure(y, &b));
            let db = self.mul_const_pure(&b, d);
            let ea = self.mul_const_pure(&a, e);
            let mut z = self.add_pure(&ab, &db);
            z = self.add_pure(&z, &ea);
            z[0] = self.m.add(z[0], self.m.mul(d, e));
            out.push(z);
        }
        out
    }

    fn open_batch(&mut self, values: &[Additive]) -> Vec<u64> {
        self.charge(values.len() as u64);
        self.counters.opens += values.len() as u64;
        values.iter().map(|s| self.reconstruct(s)).collect()
    }

    fn random_bits(&mut self, n: usize) -> Vec<Additive> {
        // Same simplification as `DealerEngine`: counted as preprocessing, drawn
        // locally rather than executed. See `crate::mpcc::vm`.
        self.counters.random_bits += n as u64;
        let mut rng = rand::thread_rng();
        (0..n)
            .map(|_| {
                let bit = u64::from(rng.gen::<bool>());
                self.split(bit)
            })
            .collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The triples must be real: `c = a·b` over the ring, with the shares of each
    /// summing to the right value. If Gilboa's OLE were wrong this is what would
    /// catch it, and every program running on this engine depends on it.
    #[test]
    fn ot_generated_triples_are_correct() {
        let mut e = Semi2kEngine::new(2, 64).unwrap();
        e.batch = 8;
        e.refill().unwrap();
        assert_eq!(e.pool.len(), 8);
        for (a, b, c) in &e.pool {
            let (av, bv, cv) = (e.reconstruct(a), e.reconstruct(b), e.reconstruct(c));
            assert_eq!(cv, av.wrapping_mul(bv), "triple is not a triple");
        }
    }

    /// Beaver multiplication over those triples must compute the product.
    #[test]
    fn multiplication_is_correct() {
        let mut e = Semi2kEngine::new(2, 64).unwrap();
        for (x, y) in [(6u64, 7u64), (0, 5), (u64::MAX, 3), (12345, 67890)] {
            let xs = e.input(x, 0);
            let ys = e.input(y, 1);
            let zs = e.mul_batch(&[(xs, ys)]);
            let got = e.open_batch(&zs)[0];
            assert_eq!(got, x.wrapping_mul(y), "{x} * {y}");
        }
    }

    /// **The measurement this engine exists for.** Offline bytes per triple must
    /// match what `mpcc::ot_cost` predicts from measured OT — that figure is what
    /// the whole dishonest-majority arm of the FHE-vs-MPC claim rests on.
    #[test]
    fn measured_offline_cost_matches_the_prediction() {
        let mut e = Semi2kEngine::new(2, 64).unwrap();
        // A batch large enough that the OT extension's base phase amortizes, which
        // is the regime the prediction is stated in.
        e.batch = 256;
        e.refill().unwrap();

        // Per triple *generated* — offline cost amortizes over the batch, so the
        // consumed count is the wrong denominator.
        let measured = e.counters().offline_bytes as f64 / e.counters().triples_generated as f64;
        let predicted = crate::mpcc::ot_cost::OtTriples::PASSIVE.triple_bytes(64);
        // Measured 3104 B/triple against a predicted 3136 on 2026-07-28 — a 1%
        // agreement, which is what turns the dishonest-majority arm of
        // research-agenda.md §4 from a prediction into a measured result.
        let ratio = measured / predicted;
        assert!(
            (0.85..=1.15).contains(&ratio),
            "measured {measured:.0} B/triple vs predicted {predicted:.0} \
             ({ratio:.2}x) — if this drifts, `ot_cost`'s Gilboa derivation or the \
             OT cost it prices from has changed, and research-agenda.md §4 depends \
             on it"
        );
    }

    #[test]
    fn more_than_two_parties_is_refused() {
        assert!(Semi2kEngine::new(3, 64).is_err());
        assert!(Semi2kEngine::new(1, 64).is_err());
    }
}
